const sections: PrayerSection[] = [{"id":"blessings-on-enjoyments","heading":"Blessings on Enjoyments","lines":[{"he":"ברכות הנהנין","en":"Blessings on Enjoyments"},{"he":"על תבשיל מחמשת מיני דגן ועל מאפה ממינים אלה (חוץ מן הלחם), ועל האורז מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי מְזוֹנוֹת:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates varieties of foods"},{"he":"על היין מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הַגֶּֽפֶן:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates fruit of the vine"},{"he":"על פירות העץ מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הָעֵץ:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates fruit of the tree"},{"he":"על פירות האדמה מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הָאֲדָמָה:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates fruit of the ground"},{"he":"על דבר שאין גדולו מן הארץ כגון בשר, דגים, חלב, גבינה, וכדומה. וכן על משקים (חוץ מן היין) מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ:","en":"Blessed are You, L·rd, Our G·d, King of the Universe that all was (made) by His word"},{"he":"לאחר האכילה אם אכל כזית בכדי אכילת פרס (4 דקות, וי\"א 8 דקות), או שתה רביעית בבת אחת על פרות האילן (חוץ מן הז' מינים), פרות האדמה, ודבר שאין גידולו מן הארץ, מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן עַל כָּל־מַה־שֶּׁבָּרָֽאתָ לְהַחֲיוֹת בָּהֶם נֶֽפֶשׁ כָּל־חָי, בָּרוּךְ חַי הָעוֹלָמִים.","en":"Blessed are You, L·rd, our G·d, King of the universe, Who creates Many Souls, & their lackings on all that You created to give life to them – all living souls. Blessed is He Who lives Forever."},{"he":"על ריח טוב שבעצים מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא עֲצֵי בְשָׂמִים:"},{"he":"על ריח טוב שבעשבים מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא עִשְׂבֵּי בְשָׂמִים:"},{"he":"על ריח טוב שאינו עץ ולא עשב, או שהוא מסופק בו בין עץ לעשב, מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי בְשָׂמִים:"},{"he":"כל בגד שהוא שמח בו, אפילו שלאחרים אין שמחה בבגד זה הרי זה מברך שהחיינו, וכן להיפך. וכן מברכים שהחיינו על פרי המתחדש משנה לשנה, ויש זמן קבוע לגידולו. אבל פירות שאין בהם היכר בין ישנים לחדשים, כגון אגוזים, שקדים, ותפוחים שנמצאים בשוק כל השנה וכדומה, אף על פי שהם מתחדשים משנה לשנה, ויודע באלו שהם חדשים, אפילו הכי לא יברך עליהם שהחיינו, מאחר שאין היכר בין חדשים לישנים. המנהג הוא לברך באכילת פרי חדש ברכת הפרי ואחר כך שהחיינו","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, שֶׁהֶחֱיָֽנוּ וְקִיְּמָֽנוּ וְהִגִּיעָֽנוּ לַזְּמַן הַזֶּה:"}]},{"id":"al-hamihya","heading":"Al Hamihya","lines":[{"he":"ברכת מעין שלוש"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם"},{"he":"אם אכל מזונות יאמר עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה","note":true},{"he":"אם שתה יין יאמר (וְ)עַל הַגֶּֽפֶן וְעַל פְּרִי הַגֶּֽפֶן","note":true},{"he":"אם אכל פרות משבעת המינים יאמר (וְ)עַל הָעֵץ וְעַל פְּרִי הָעֵץ","note":true},{"he":"וְעַל תְּנוּבַת הַשָּׂדֶה, וְעַל אֶֽרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה, שֶׁרָצִֽיתָ וְהִנְחַֽלְתָּ לַאֲבוֹתֵֽינוּ, לֶאֱכֹל מִפִּרְיָהּ וְלִשְׂבֹּֽעַ מִטּוּבָהּ. רַחֵם יְהֹוָה אֱלֹהֵֽינוּ עָלֵֽינוּ וְעַל יִשְׂרָאֵל עַמָּךְ, וְעַל יְרוּשָׁלַֽיִם עִירָךְ, וְעַל הַר צִיּוֹן מִשְׁכַּן כְּבוֹדָךְ, וְעַל מִזְבָּחָךְ וְעַל הֵיכָלָךְ. וּבְנֵה יְרוּשָׁלַֽיִם עִיר הַקֹּֽדֶשׁ בִּמְהֵרָה בְיָמֵֽינוּ, וְהַעֲלֵֽנוּ לְתוֹכָהּ, וְשַׂמְּחֵֽנוּ בְּבִנְיָנָהּ, וּנְבָֽרְכָֽךְ עָלֶֽיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה:"},{"he":"בשבת וּרְצֵה וְהַחֲלִיצֵֽנוּ בְּיוֹם הַשַּׁבָּת הַזֶּה.","note":true},{"he":"בראש־חודש וְזָכְרֵֽנוּ לְטוֹבָה בְּיוֹם רֹאשׁ חֹֽדֶשׁ הַזֶּה.","note":true},{"he":"בראש־השנה וְזָכְרֵֽנוּ לְטוֹבָה בְּיוֹם הַזִּכָּרוֹן הַזֶּה.","note":true},{"he":"בפסח וְשַׂמְּחֵֽנוּ בְּיוֹם חַג הַמַּצּוֹת הַזֶּה, בְּיוֹם ביום טוב: טוֹב מִקְרָא קֹדֶשׁ הַזֶּה.","note":true},{"he":"בשבועות וְשַׂמְּחֵֽנוּ בְּיוֹם חַג הַשָּׁבוּעוֹת הַזֶּה בְּיוֹם טוֹב מִקְרָא קֹֽדֶשׁ הַזֶּה.","note":true},{"he":"בסוכות וְשַׂמְּחֵֽנוּ בְּיוֹם הַסֻּכּוֹת הַזֶּה, בְּיוֹם ביום טוב: טוֹב מִקְרָא קֹֽדֶשׁ הַזֶּה.","note":true},{"he":"בשמיני עצרת וְשַׂמְּחֵֽנוּ בְּיוֹם שְׁמִינִי חַג עֲצֶֽרֶת הַזֶּה בְּיוֹם טוֹב מִקְרָא קֹֽדֶשׁ הַזֶּה.","note":true},{"he":"כִּי אַתָּה טוֹב וּמֵטִיב לַכֹּל, וְנוֹדֶה לְךָ עַל הָאָֽרֶץ"},{"he":"מזונות וְעַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה של ארץ ישראל וְעַל מִחְיָתָהּ וְעַל כַּלְכָּלָתָהּ","note":true},{"he":"יין וְעַל פְּרִי הַגֶּֽפֶן של ארץ ישראל וְעַל פְּרִי גַפְנָהּ","note":true},{"he":"פירות וְעַל הַפֵּרוֹת של ארץ ישראל וְעַל פֵּרוֹתֶֽיהָ","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, עַל הָאָֽרֶץ וְעַל"},{"he":"מזונות הַמִּחְיָה וְעַל הַכַּלְכָּלָה: של ארץ ישראל מִחְיָתָהּ וְעַל כַּלְכָּלָתָהּ:","note":true},{"he":"יין פְּרִי הַגֶּֽפֶן: של ארץ ישראל פְּרִי גַפְנָהּ:","note":true},{"he":"פירות הַפֵּרוֹת: של ארץ ישראל פֵּרוֹתֶֽיהָ:","note":true}]}];

export default sections;
